// Salud del inventario (spec 037): lo que hace que las existencias no cuadren. Solo lectura; la
// escritura del cambio de modo vive en stock.sql.
//
// Cada lista trae su total con count(*) over() sobre el MISMO `where`, para que el número de la
// sección y sus renglones no puedan divergir. La empresa la pone RLS.
// «Se vende sin restar»: lo vendido en el periodo que no dejó ningún movimiento de venta. Se mide
// sobre lo que pasó y no sobre la configuración: un producto cuyo sabor obligatorio resta no es
// problema, y el sabor que no resta sí (research R2). Tres fuentes, cada una con su prueba:
//   - el renglón de un producto suelto (los paquetes se miden por sus piezas);
//   - cada extra del renglón;
//   - cada pieza de un paquete (order_line_components, la copia hecha al vender).
//
// Lo confirmado «No gasta insumos» no es problema (FR-004). composition_status va con coalesce: es
// NULL en lo nunca decidido, y `not (NULL and …)` es NULL, que el `where` descarta: justo lo que
// más importa mostrar desaparecería. El producto genérico de plataforma va
// en HealthUnpairedLines, no aquí.
func (q *Queries) HealthUnsold(ctx context.Context, arg HealthUnsoldParams) ([]HealthUnsoldRow, error) {
	rows, err := q.db.Query(ctx, healthUnsold,
		arg.Off,
		arg.Lim,
		arg.FromDate,
		arg.ToDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HealthUnsoldRow{}
	for rows.Next() {
		var i HealthUnsoldRow
		if err := rows.Scan(
			&i.Kind,
			&i.ID,
			&i.Name,
			&i.Grp,
			&i.Pieces,
			&i.Lines,
			&i.Units,
			&i.EstimatedCost,
			&i.TrackStock,
			&i.ProductType,
			&i.HasRecipeItems,
			&i.IsLinked,
			&i.CompositionStatus,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
